{"command":"cd /home/carlos-andr-ferreira/viriato-bench/runs/pi-qwen3.8-t02-v1-polygon-2 && node -e "
const fs = require('fs');
const code = fs.readFileSync('index.html','utf8').match(/<script>([\s\S]*)<\/script>/)[1];
function fresh(){
  const ctxStub = new Proxy({}, { get: (t,p)=> (p==='canvas' ? canvas : function(){}), set: ()=>true });
  const canvas = { width:640, height:640, getContext: ()=>ctxStub };
  const sandbox = { document:{getElementById:()=>canvas}, window:{}, performance:{now:()=>0}, requestAnimationFrame:()=>{}, Math, console };
  const vm = require('vm'); vm.createContext(sandbox); vm.runInContext(code, sandbox);
  return sandbox.window.__bench;
}
// determinism check
const a = fresh(), b = fresh();
for(let i=0;i<720;i++){ a.step(1/60); b.step(1/60); }
const sa = JSON.stringify(a.getState()), sb = JSON.stringify(b.getState());
console.log('deterministic:', sa === sb);

// stress: 5 minutes of simulation incl. variable dt
const c = fresh();
let maxOut=0, maxOv=0;
for(let i=0;i<6000;i++){
  c.step(0.008 + (i%7)*0.004); // 8–32 ms variable steps
  if(i%100===0){
    const st=c.getState();
    const inr=260*Math.cos(Math.PI/9)-14;
    let bo=0;
    for(const bl of st.balls){
      if(!isFinite(bl.x)||!isFinite(bl.y)||!isFinite(bl.vx)||!isFinite(bl.vy)){console.log('NONFINITE at i=',i); process.exit(1);}
      bo=Math.max(bo, Math.hypot(bl.x-320,bl.y-320));
    }
    maxOut=Math.max(maxOut,bo);
    for(let x=0;x<13;x++)for(let y=x+1;y<13;y++){
      const p=st.balls[x],q=st.balls[y];
      maxOv=Math.max(maxOv, 28-Math.hypot(p.x-q.x,p.y-q.y));
    }
  }
}
console.log('maxDistFromCenter:', maxOut.toFixed(4), 'inradius ballLimit:', inr);
console.log('maxOverlap(px):', maxOv.toFixed(5), '(<0 means no overlap)');
"
"}

