// ---- Positional separation (no velocity changes) -------------------------

// Depth of a ball center from an edge (positive = inside). Also returns the
// inward normal. `out` receives {pen, nx, ny, t} with the closest-point
// parameter on the edge segment.
function edgeInfo(A, B, ex, ey, L, ball, out) {
  let nx = -ey / L, ny = ex / L;
  if (nx * (CX - A.x) + ny * (CY - A.y) < 0) { nx = -nx; ny = -ny; }
  const depth = (ball.x - A.x) * nx + (ball.y - A.y) * ny;
  out.pen = CFG.ballR - depth;
  out.nx = nx; out.ny = ny;
}

// Push a ball out of every edge it penetrates (deepest one wins).
function pushBallInner(ball, verts, edges) {
  let best = 0, bx = 0, by = 0;
  for (let i = 0; i < CFG.n; i++) {
    const e = edges[i];
    let nx = -e.ey / e.len, ny = e.ex / e.len;
    if (nx * (CX - e.ax) + ny * (CY - e.ay) < 0) { nx = -nx; ny = -ny; }
    const pen = CFG.ballR - ((ball.x - e.ax) * nx + (ball.y - e.ay) * ny);
    if (pen > best) { best = pen; bx = nx; by = ny; }
  }
  if (best > 0) { ball.x += bx * best; ball.y += by * best; return true; }
  return false;
}

function buildEdges() {
  const verts = polyVerts(sim.angle);
  const edges = [];
  for (let i = 0; i < CFG.n; i++) {
    const A = verts[i], B = verts[(i + 1) % CFG.n];
    const ex = B.x - A.x, ey = B.y - A.y;
    edges.push({ ax: A.x, ay: A.y, ex, ey, len: Math.hypot(ex, ey) });
  }
  return edges;
}

function separateWalls() {
  const edges = buildEdges();
  let touched = false;
  for (const ball of sim.balls) {
    if (pushBallInner(ball, null, edges)) touched = true;
  }
  // Safety net: a ball that somehow ends up outside the whole polygon is
  // pulled back inside the apothem.
  const inradius = CFG.radius * Math.cos(Math.PI / CFG.n) - CFG.ballR - 0.5;
  for (const ball of sim.balls) {
    const dx = ball.x - CX, dy = ball.y - CY;
    const d = Math.hypot(dx, dy);
    if (d > inradius) {
      const s = inradius / (d || 1);
      ball.x = CX + dx * s; ball.y = CY + dy * s;
      touched = true;
    }
  }
  return touched;
}

function separateBalls() {
  const b = sim.balls;
  const minDist = CFG.ballR * 2;
  let touched = false;
  for (let i = 0; i < b.length; i++) {
    for (let j = i + 1; j < b.length; j++) {
      const a = b[i], c = b[j];
      const dx = c.x - a.x, dy = c.y - a.y;
      const d2 = dx * dx + dy * dy;
      if (d2 >= minDist * minDist) continue;
      let d = Math.sqrt(d2), nx, ny;
      if (d < 1e-9) { nx = 1; ny = 0; d = 1e-9; } else { nx = dx / d; ny = dy / d; }
      const ov = (minDist - d) * 0.5;
      a.x -= nx * ov; a.y -= ny * ov;
      c.x += nx * ov; c.y += ny * ov;
      touched = true;
    }
  }
  return touched;
}

// ---- Velocity impulses (single pass) --------------------------------------

function impulseBallBall() {
  const b = sim.balls;
  const minDist = CFG.ballR * 2;
  for (let i = 0; i < b.length; i++) {
    for (let j = i + 1; j < b.length; j++) {
      const a = b[i], c = b[j];
      const dx = c.x - a.x, dy = c.y - a.y;
      const d2 = dx * dx + dy * dy;
      if (d2 >= minDist * minDist) continue;
      let d = Math.sqrt(d2), nx, ny;
      if (d < 1e-9) { nx = 1; ny = 0; d = 1e-9; } else { nx = dx / d; ny = dy / d; }

      const rvx = c.vx - a.vx, rvy = c.vy - a.vy;
      const vn = rvx * nx + rvy * ny;
      if (vn < 0) {
        const e = CFG.restitution;
        const jImp = -(1 + e) * vn * 0.5;   // equal masses
        a.vx -= jImp * nx; a.vy -= jImp * ny;
        c.vx += jImp * nx; c.vy += jImp * ny;

        // tangential contact friction (Coulomb bound)
        const tx = -ny, ty = nx;
        const vt = rvx * tx + rvy * ty;
        const maxF = CFG.contactMu * (1 + e) * (-vn) * 0.5;
        const f = Math.min(Math.abs(vt), maxF) * (vt >= 0 ? 1 : -1);
        a.vx += f * tx; a.vy += f * ty;
        c.vx -= f * tx; c.vy -= f * ty;
      }
    }
  }
}

function impulseWalls() {
  const edges = buildEdges();
  for (const ball of sim.balls) {
    // deepest edge for this ball
    let pen = 0, nx = 0, ny = 0, e = null;
    for (let i = 0; i < CFG.n; i++) {
      const edge = edges[i];
      let ex2 = -edge.ey / edge.len, ny2 = edge.ex / edge.len;
      if (ex2 * (CX - edge.ax) + ny2 * (CY - edge.ay) < 0) { ex2 = -ex2; ny2 = -ny2; }
      const p = CFG.ballR - ((ball.x - edge.ax) * ex2 + (ball.y - edge.ay) * ny2);
      if (p > pen) { pen = p; nx = ex2; ny = ny2; e = edge; }
    }
    if (pen < -1e-3) continue; // not in contact with this edge region

    // contact point: closest point on the segment
    let tproj = ((ball.x - e.ax) * e.ex + (ball.y - e.ay) * e.ey) / (e.ex * e.ex + e.ey * e.ey);
    tproj = tproj < 0 ? 0 : (tproj > 1 ? 1 : tproj);
    const px = e.ax + tproj * e.ex, py = e.ay + tproj * e.ey;

    // wall velocity at the contact point (rigid rotation about the center)
    const wx = CFG.omega * (-(py - CY));
    const wy = CFG.omega * (px - CX);

    const rvx = ball.vx - wx, rvy = ball.vy - wy;
    const vn = rvx * nx + rvy * ny;
    if (vn < 0) {
      const dv = -(1 + CFG.restitution) * vn;   // restitution on the normal
      ball.vx += dv * nx;
      ball.vy += dv * ny;

      // tangential friction against the moving wall (Coulomb bound)
      const tx = -ny, ty = nx;
      const vt = rvx * tx + rvy * ty;
      const maxF = CFG.contactMu * (1 + CFG.restitution) * (-vn);
      const f = Math.min(Math.abs(vt), maxF) * (vt >= 0 ? 1 : -1);
      ball.vx -= f * tx;
      ball.vy -= f * ty;
    }
  }
}

// Deterministic advance by dtSeconds.
sim.step = function (dt) {
  if (!(dt > 0)) return;
  const sub = Math.max(1, Math.ceil(dt / CFG.maxSubstep));
  const h = dt / sub;
  for (let s = 0; s < sub; s++) {
    sim.t += h;
    sim.angle = sim.t * CFG.omega;      // clockwise rotation

    // integrate
    for (const b of sim.balls) {
      b.vy += CFG.gravity * h;
      const drag = 1 - Math.min(1, CFG.airDrag * h);
      b.vx *= drag;
      b.vy *= drag;
      b.x += b.vx * h;
      b.y += b.vy * h;
      b.rot += (b.vx / CFG.ballR) * h;  // number spins with the ball
    }

    // positional constraints: iterate until no penetration remains (capped)
    for (let it = 0; it < 64; it++) {
      const w = separateWalls();
      const c = separateBalls();
      if (!w && !c) break;
    }

    // velocity responses (single pass)
    impulseWalls();
    impulseBallBall();
  }
};

