    if(!isFinite(bl.x)||!isFinite(bl.y)||!isFinite(bl.vx)||!isFinite(bl.vy)){ console.log(label,'NONFINITE id',bl.id); bad++; }
    if(Math.hypot(bl.x-320,bl.y-320) > inr + 1e-6){ console.log(label,'OUT id',bl.id, Math.hypot(bl.x-320,bl.y-320).toFixed(4)); bad++; }
  }
  let maxOv = 0;
  for(let i=0;i<13;i++)for(let j=i+1;j<13;j++){
    const p=st.balls[i],q=st.balls[j];
    const ov=28-Math.hypot(p.x-q.x,p.y-q.y);
    if(ov>maxOv)maxOv=ov;
  }
  if(maxOv>1e-6){console.log(label,'MAX OVERLAP',maxOv.toExponential(2));bad++;}
  if(!Math.abs(Math.abs(st.balls.length-13)))bad++;
  if(Math.abs(st.poly.angle - st.t*2*Math.PI/7) > 1e-9){console.log(label,'ANGLE MISMATCH');bad++;}
  return bad;
}
