for(let i=0;i<200;i++){c.step(1/60);d.step(1/60);}
console.log('deterministic:', JSON.stringify(c.getState())===JSON.stringify(d.getState()));
// 4) state shape
const s=a.getState();
console.log('top keys:', Object.keys(s).sort().join(','), '| poly:', JSON.stringify(s.poly), '| ball:', JSON.stringify(Object.keys(s.balls[0]).sort().join(',')));
console.log('perf: 7200 mixed steps in', perf, 'ms');
console.log(fails===0 ? 'ALL CHECKS PASS' : 'FAILURES: '+fails);
"
