  // pre-allocated per-substep edge data
  const eAx = new Float64Array(9), eAy = new Float64Array(9),
        eNx = new Float64Array(9), eNy = new Float64Array(9),
        eEx = new Float64Array(9), eEy = new Float64Array(9), eL2 = new Float64Array(9);

  function computeEdges() {
    const angle = sim.angle, stepA = TAU / CFG.n, R = CFG.radius;
    let ca = Math.cos(angle), sa = Math.sin(angle);
    for (let i = 0; i < CFG.n; i++) {
      const a1 = angle + i * stepA, a2 = angle + (i + 1) * stepA;
      const ax = CX + Math.cos(a1) * R, ay = CY + Math.sin(a1) * R;
      const bx = CX + Math.cos(a2) * R, by = CY + Math.sin(a2) * R;
      const ex = bx - ax, ey = by - ay;
      const len = Math.sqrt(ex * ex + ey * ey);
      let nx = -ey / len, ny = ex / len;
      if (nx * (CX - ax) + ny * (CY - ay) < 0) { nx = -nx; ny = -ny; }
      eAx[i] = ax; eAy[i] = ay; eNx[i] = nx; eNy[i] = ny;
      eEx[i] = ex; eEy[i] = ey; eL2[i] = ex * ex + ey * ey;
    }
  }
