// ---- Precomputed edge data (rebuilt once per substep) ---------------------
const N = CFG.n;
const eAx = new Float64Array(N), eAy = new Float64Array(N);
const eEx = new Float64Array(N), eEy = new Float64Array(N), eL2 = new Float64Array(N);
const eNx = new Float64Array(N), eNy = new Float64Array(N);

function computeEdges() {
  const stepA = TAU / N, R = CFG.radius;
  for (let i = 0; i < N; i++) {
    const a1 = sim.angle + i * stepA, a2 = sim.angle + (i + 1) * stepA;
    const ax = CX + Math.cos(a1) * R, ay = CY + Math.sin(a1) * R;
    const bx = CX + Math.cos(a2) * R, by = CY + Math.sin(a2) * R;
    const ex = bx - ax, ey = by - ay;
    const len = Math.sqrt(ex * ex + ey * ey);
    let nx = -ey / len, ny = ex / len;   // inward (toward the center)
    if (nx * (CX - ax) + ny * (CY - ay) < 0) { nx = -nx; ny = -ny; }
    eAx[i] = ax; eAy[i] = ay; eEx[i] = ex; eEy[i] = ey; eL2[i] = ex * ex + ey * ey;
    eNx[i] = nx; eNy[i] = ny;
  }
}

// ---- Positional separation (no velocity changes) -------------------------

// Project ball centers out of walls and out of each other until all
// penetrations drop below tol (capped). Deterministic.
function converge(tol) {
  const balls = sim.balls, B = balls.length;
  const R = CFG.ballR, minD = R + R, minD2 = minD * minD;
  for (let it = 0; it < 500; it++) {
    let maxF = 0;
    // deepest wall per ball
    for (let k = 0; k < B; k++) {
      const b = balls[k];
      let best = 0, bnx = 0, bny = 0;
      for (let i = 0; i < N; i++) {
        const pen = R - ((b.x - eAx[i]) * eNx[i] + (b.y - eAy[i]) * eNy[i]);
        if (pen > best) { best = pen; bnx = eNx[i]; bny = eNy[i]; }
      }
      if (best > 0) {
        b.x += bnx * best; b.y += bny * best;
        if (best > maxF) maxF = best;
      }
    }
    // pairwise ball overlap
    for (let i = 0; i < B; i++) {
      const a = balls[i];
      for (let j = i + 1; j < B; j++) {
        const c = balls[j];
        const dx = c.x - a.x, dy = c.y - a.y;
        const d2 = dx * dx + dy * dy;
        if (d2 >= minD2) continue;
        const d = Math.sqrt(d2);
        if (d > 1e-9) {
          const s = (minD - d) / (2 * d);
          a.x -= dx * s; a.y -= dy * s;
          c.x += dx * s; c.y += dy * s;
          const ov = minD - d;
          if (ov > maxF) maxF = ov;
        } else {
          a.x -= minD * 0.5;   // (effectively impossible) coincident centers
          maxF = minD;
        }
      }
    }
    if (maxF <= tol) break;
  }

  // safety net: no ball may ever end up outside the polygon
  const inradius = CFG.radius * Math.cos(Math.PI / N) - R - 0.5;
  for (const b of balls) {
    const dx = b.x - CX, dy = b.y - CY;
    const d = Math.sqrt(dx * dx + dy * dy);
    if (d > inradius) {
      const s = inradius / (d || 1);
      b.x = CX + dx * s; b.y = CY + dy * s;
      const out = (b.vx * dx + b.vy * dy) / (d || 1);
      if (out > 0) { b.vx -= out * dx / (d || 1); b.vy -= out * dy / (d || 1); }
    }
  }
}

// ---- Velocity impulses (single pass) --------------------------------------

function impulseBallBall() {
  const balls = sim.balls, B = balls.length;
  const minD = CFG.ballR * 2, minD2 = minD * minD;
  const e = CFG.restitution;
  for (let i = 0; i < B; i++) {
    const a = balls[i];
    for (let j = i + 1; j < B; j++) {
      const c = balls[j];
      const dx = c.x - a.x, dy = c.y - a.y;
      const d2 = dx * dx + dy * dy;
      if (d2 >= minD2) continue;
      let d = Math.sqrt(d2), nx, ny;
      if (d < 1e-9) { nx = 1; ny = 0; d = 1e-9; } else { nx = dx / d; ny = dy / d; }

      const rvx = c.vx - a.vx, rvy = c.vy - a.vy;
      const vn = rvx * nx + rvy * ny;
      if (vn < 0) {
        const jImp = -(1 + e) * vn * 0.5;   // equal masses
        a.vx -= jImp * nx; a.vy -= jImp * ny;
        c.vx += jImp * nx; c.vy += jImp * ny;

        // tangential contact friction (Coulomb bound)
        const tx = -ny, ty = nx;
        const vt = rvx * tx + rvy * ty;
        const maxF = CFG.contactMu * (1 + e) * (-vn) * 0.5;
        const f = Math.min(Math.abs(vt), maxF) * (vt >= 0 ? 1 : -1);
        a.vx += f * tx; a.vy += f * ty;
        c.vx -= f * tx; c.vy -= f * ty;
      }
    }
  }
}

function impulseWalls() {
  const balls = sim.balls, B = balls.length;
  const e = CFG.restitution;
  for (let k = 0; k < B; k++) {
    const ball = balls[k];
    // deepest edge
    let pen = -8e15, bi = 0;
    for (let i = 0; i < N; i++) {
      const p = CFG.ballR - ((ball.x - eAx[i]) * eNx[i] + (ball.y - eAy[i]) * eNy[i]);
      if (p > pen) { pen = p; bi = i; }
    }
    if (pen < -1e-6) continue; // not near any wall, no impulse

    const nx = eNx[bi], ny = eNy[bi];
    // contact point: closest point on the segment
    let t = ((ball.x - eAx[bi]) * eEx[bi] + (ball.y - eAy[bi]) * eEy[bi]) / eL2[bi];
    t = t < 0 ? 0 : (t > 1 ? 1 : t);
    const px = eAx[bi] + t * eEx[bi], py = eAy[bi] + t * eEy[bi];

    // wall velocity at the contact point (rigid rotation about the center)
    const wx = CFG.omega * (-(py - CY));
    const wy = CFG.omega * (px - CX);

    const rvx = ball.vx - wx, rvy = ball.vy - wy;
    const vn = rvx * nx + rvy * ny;
    if (vn < 0) {
      const dv = -(1 + e) * vn;   // restitution on the normal component
      ball.vx += dv * nx;
      ball.vy += dv * ny;

      // tangential friction against the moving wall (Coulomb bound)
      const tx = -ny, ty = nx;
      const vt = rvx * tx + rvy * ty;
      const maxF = CFG.contactMu * (1 + e) * (-vn);
      const f = Math.min(Math.abs(vt), maxF) * (vt >= 0 ? 1 : -1);
      ball.vx -= f * tx;
      ball.vy -= f * ty;
    }
  }
}

